const allToolTranslations: Record<string, ToolTranslationMap> = {
  en, ru, es, fr, de, it, pt, zh, ja, ko, ar, tr, hi, pl, nl, uk, vi, id, th, cs,
};

export function getToolTranslation(slug: string, lang: LangCode): ToolTranslation {
  const langMap = allToolTranslations[lang];
  if (langMap && langMap[slug]) return langMap[slug];
  return allToolTranslations.en[slug] || { name: slug, description: "" };
}
